# ---- server ----------------------------------------------------------------------------------------------------
server <- function(input, output, session) {
  # TRUE when the controls (as summarised by sig()) differ from what they were when the button was last pressed
  stale_flag <- function(button, sig) {
    ran <- reactiveVal(NULL)
    observeEvent(input[[button]], ran(sig()))
    reactive(!is.null(ran()) && !identical(ran(), sig()))
  }
  output$example_picker <- renderUI(selectInput("example", "Example", examples[[input$design]]))
  setup <- reactive(if (input$src == "ex" && !is.null(input$example) && input$example %in% names(example_setup)) example_setup[[input$example]])

  dat <- reactive({
    if (input$src == "ex") { s <- setup(); req(s); return(read.csv(s$file)) }
    req(input$file)
    # every column is read as text so that the engine can check and convert it (decimal commas, units, "n/a", ...)
    tryCatch(star_read_table(input$file$datapath, input$file$name),
             error = function(e) { showNotification(paste("Could not read the file:", conditionMessage(e)), type = "error"); req(FALSE) })
  })
  output$data_ui <- renderUI(data_preview_ui(dat()))
  output$var_pickers <- renderUI({
    nm <- names(dat()); s <- setup()
    tagList(
      selectInput("resp", "Response variable", nm, selected = if (!is.null(s)) s$resp else tail(nm, 1)),
      if (input$design == "SplitRCBD") tagList(
        selectInput("trt_main", "Main-plot factor", nm, selected = if (!is.null(s)) s$trt[1] else nm[min(2, length(nm))]),
        selectInput("trt_sub", "Sub-plot factor", nm, selected = if (!is.null(s)) s$trt[2] else nm[min(3, length(nm))]))
      else selectizeInput("trt", "Treatment factor(s): one or two", nm, multiple = TRUE,
                     selected = if (!is.null(s)) s$trt else nm[min(2, length(nm))], options = list(maxItems = 2)),
      if (input$design != "CRD") selectInput("blk", "Block / replication", nm, selected = if (!is.null(s)) s$blk else nm[1])
    )
  })

  # Runs on "Run ANOVA" only. Results are cached by data and settings, so going back to an earlier choice
  # (e.g. LSD -> Tukey -> LSD) reuses the earlier result instead of analysing again. The classic STAR report is
  # built later, only when it is viewed, copied or downloaded (see report_text).
  res <- reactive({
    req(input$resp)
    blk <- if (input$design != "CRD") { req(input$blk); input$blk } else NULL
    if (input$design == "SplitRCBD") {
      req(input$trt_main, input$trt_sub)
      return(tryCatch(star_splitplot(dat(), input$resp, input$trt_main, input$trt_sub, blk, test = input$pw,
                                     alpha = as.numeric(input$alpha), report = FALSE),
                      error = function(e) structure(list(message = conditionMessage(e)), class = "star_error")))
    }
    req(input$trt)
    tryCatch(star_aov(dat(), input$resp, input$trt, blk, design = input$design, test = input$pw,
                      alpha = as.numeric(input$alpha), report = FALSE),
             error = function(e) structure(list(message = conditionMessage(e)), class = "star_error"))
  }) |>
    bindCache(dat(), input$design, input$resp, input$trt, input$trt_main, input$trt_sub, input$blk, input$pw, input$alpha) |>
    bindEvent(input$go_aov)
  ok <- reactive({ r <- res(); req(!inherits(r, "star_error")); r })
  # The data behind the current results (for plotting observations). Stored when Run is pressed: an eventReactive would
  # only read the data when first asked for, by which time the user may have switched to another example.
  used_data <- reactiveVal(NULL)
  observeEvent(input$go_aov, used_data(dat()))
  aov_sig <- reactive(list(input$design, input$src, input$example, input$file$name, input$resp, input$trt, input$trt_main, input$trt_sub,
                           input$blk, input$pw, input$alpha))
  aov_stale <- stale_flag("go_aov", aov_sig)
  output$aov_msg <- renderUI({
    if (!isTRUE(input$go_aov > 0)) return(run_hint("Run ANOVA"))
    r <- res()
    tagList(if (aov_stale()) stale_note(), if (inherits(r, "star_error")) div(class = "alert alert-danger", r$message))
  })

  # tables prepared once so that the screen, the clipboard and the Excel file agree
  tables <- reactive({
    r <- ok(); fs <- r$factors
    out <- list(anova = anova_display(r$anova), means = list(), cells = NULL, simple = list())
    for (f in fs) {
      show <- isTRUE(r$effects$Significant[r$effects$Effect == f]) && !r$interaction_significant
      out$means[[f]] <- means_display(r$means[[f]], f, show)
    }
    if (!is.null(r$cells)) out$cells <- cells_display(r$cells, fs[1], fs[2])
    for (nm in names(r$simple)) out$simple[[nm]] <- simple_display(r$simple[[nm]])
    out
  })

  output$results_ui <- renderUI({
    r <- ok(); tb <- tables()
    tagList(
      if (length(r$data_notes)) div(class = "alert alert-warning", strong("Data checks"),
                                    tags$ul(lapply(r$data_notes, tags$li))),
      div(class = if (r$significant || r$interaction_significant) "alert alert-success" else "alert alert-info", r$summary),
      h4("Analysis of variance"), actionButton("cp_anova", "Copy table"), html_table(tb$anova),
      actionButton("cp_means", "Copy means tables"),
      lapply(names(tb$means), function(f) tagList(h4(paste("Means of", f)), html_table(tb$means[[f]]))),
      if (!is.null(tb$cells)) tagList(h4(paste("Cell means:", paste(r$factors, collapse = " x "))), html_table(tb$cells)),
      lapply(names(tb$simple), function(nm) {
        sm <- r$simple[[nm]]
        tagList(h4(sprintf("Comparison of %s at each level of %s (%s test)", attr(sm, "compare"), attr(sm, "at"), attr(sm, "test"))),
                html_table(tb$simple[[nm]]),
                p(class = "text-muted", "Means with the same letter (within a column) are not significantly different."))
      }),
      h4("APA-style report"), actionButton("cp_apa", "Copy"), div(class = "well well-sm", lapply(r$apa, p))
    )
  })

  output$plot_picker <- renderUI({
    r <- ok()
    ch <- c(setNames(r$factors, paste("Means of", r$factors)), if (!is.null(r$cells)) c("Interaction (grouped bars)" = "interaction", if (use_gg()) c("Interaction (lines)" = "interaction_line")))
    cur <- isolate(input$plot_effect)   # keep the choice when the style is switched
    if (length(ch) > 1) selectInput("plot_effect", "Plot", ch, selected = if (!is.null(cur) && cur %in% ch) cur else if (r$interaction_significant) "interaction" else r$factors[1])
  })
  plot_effect <- reactive({ r <- ok(); pe <- input$plot_effect; if (is.null(pe) || !(pe %in% c(r$factors, if (!is.null(r$cells)) c("interaction", "interaction_line")))) r$factors[1] else pe })
  use_gg <- reactive(identical(input$plot_style, "gg"))
  # the ggplot2 figure (a ggplot object); the classic style is drawn with base graphics instead
  gg_means <- reactive(star_ggplot_means(ok(), plot_effect(), data = if (isTRUE(input$gg_points)) used_data(), error = input$gg_error %||% "se",
                                                main = input$gg_title, xlab = input$gg_xlab, ylab = input$gg_ylab))
  draw_means <- function() {
    if (use_gg()) print(gg_means())
    else star_plot_means(ok(), sub("_line$", "", plot_effect()), main = input$gg_title, xlab = input$gg_xlab, ylab = input$gg_ylab)
  }
  output$means_plot <- renderPlot(draw_means())
  output$diag_ui <- renderUI({
    dg <- ok()$diagnostics
    if (is.null(dg)) return(div(class = "alert alert-warning", if (identical(ok()$design, "SplitRCBD")) "Assumption checks are not available for split-plot designs yet." else "Assumption checks could not be computed for this data."))
    tagList(
      div(class = if (dg$ok) "alert alert-success" else "alert alert-warning", tags$ul(lapply(dg$messages, tags$li))),
      if (nrow(dg$outliers)) {
        o <- dg$outliers
        o[] <- lapply(o, function(v) if (is.numeric(v)) fmt_n(v, 3) else as.character(v))
        tagList(h4("Flagged observations"), p(class = "text-muted", "Row = row number in your data. |Studentized residual| > 3 = outlier, 2 to 3 = suspect."), html_table(o))
      })
  })
  output$diag_plot <- renderPlot({ dg <- ok()$diagnostics; req(dg); if (identical(input$diag_style, "gg")) print(star_ggplot_diagnostics(dg)) else star_plot_diagnostics(dg) })
  report_text <- reactive(star_report(ok())) |> bindCache(ok())
  output$report <- renderText(paste(report_text(), collapse = "\n"))

  xlsx_sheets <- reactive({
    r <- ok(); tb <- tables()
    sheets <- list(ANOVA = r$anova,
                   Means = do.call(rbind, lapply(names(tb$means), function(f) data.frame(Effect = f, r$means[[f]], row.names = NULL))))
    if (!is.null(r$cells)) sheets$`Cell means` <- r$cells
    if (length(r$simple)) sheets$`Simple effects` <- do.call(rbind, lapply(names(r$simple), function(nm) {
      sm <- r$simple[[nm]]; data.frame(Comparison = nm, setNames(sm[c(attr(sm, "at"), attr(sm, "compare"), "Mean", "N", "SE", "Group")], c("At level", "Level", "Mean", "N", "SE", "Group")), row.names = NULL)
    }))
    sheets$Info <- data.frame(Item = c("Design", "Response", "Treatment factor(s)", "Block", "Mean comparison", "Alpha", "Grand mean", "CV (%)", "Summary", "Data checks"),
                              Value = c(r$design, r$response, paste(r$factors, collapse = ", "), if (is.null(r$block)) "-" else r$block,
                                        if (r$test == "auto") "auto (LSD if <= 5 levels, else HSD)" else r$test, r$alpha,
                                        round(r$grand_mean, 4),
                                        if (is.null(r$cv_a)) round(r$cv, 2) else sprintf("CV(a) = %.2f, CV(b) = %.2f", r$cv_a, r$cv_b), r$summary,
                                        if (length(r$data_notes)) paste(r$data_notes, collapse = " | ") else "none"))
    sheets
  })
  output$dl_xlsx <- downloadHandler("star_anova.xlsx", function(file) openxlsx::write.xlsx(xlsx_sheets(), file))
  output$dl_aov_plot <- downloadHandler(function() paste0("star_means_plot.", input$aov_fmt), function(file) {
    fmt <- input$aov_fmt %||% "png"; dpi <- as.numeric(input$aov_dpi %||% 300)
    if (use_gg()) { star_ggsave(gg_means(), file, width = 8, height = 5.6, dpi = dpi); return(invisible()) }
    if (fmt == "png") png(file, width = 8 * dpi, height = 5.6 * dpi, res = dpi)
    else if (fmt == "svg") svg(file, width = 8, height = 5.6) else pdf(file, width = 8, height = 5.6)
    on.exit(dev.off()); draw_means()
  })
  output$dl_txt <- downloadHandler("star_anova_report.txt", function(file) writeLines(report_text(), file))

  observeEvent(input$cp_anova, session$sendCustomMessage("copy_text", list(what = "ANOVA table", text = tsv(tables()$anova))))
  observeEvent(input$cp_means, session$sendCustomMessage("copy_text", list(what = "Means tables", text = paste(
    c(unlist(lapply(names(tables()$means), function(f) c(paste("Means of", f), tsv(tables()$means[[f]]), ""))),
      if (!is.null(tables()$cells)) c("Cell means", tsv(tables()$cells), ""),
      unlist(lapply(names(tables()$simple), function(nm) c(nm, tsv(tables()$simple[[nm]]), "")))), collapse = "\n"))))
  observeEvent(input$cp_apa, session$sendCustomMessage("copy_text", list(what = "APA text", text = paste(ok()$apa, collapse = " "))))
  observeEvent(input$cp_report, session$sendCustomMessage("copy_text", list(what = "Report", text = paste(report_text(), collapse = "\n"))))
  observeEvent(input$copy_status, {
    st <- input$copy_status
    showNotification(if (isTRUE(st$ok)) paste(st$what, "copied to clipboard") else "Copy failed: select the text and copy manually",
                     type = if (isTRUE(st$ok)) "message" else "error", duration = 3)
  })

  # ---- shared by the correlation and regression screens ----
  use_data <- function(p, setups) reactive({
    if (input[[paste0(p, "_src")]] == "ex") { s <- setups[[input[[paste0(p, "_example")]]]]; req(s); return(read.csv(s$file)) }
    f <- input[[paste0(p, "_file")]]; req(f)
    tryCatch(star_read_table(f$datapath, f$name),
             error = function(e) { showNotification(paste("Could not read the file:", conditionMessage(e)), type = "error"); req(FALSE) })
  })
  example_of <- function(p, setups) if (input[[paste0(p, "_src")]] == "ex") setups[[input[[paste0(p, "_example")]]]]
  as_error <- function(e) structure(list(message = conditionMessage(e)), class = "star_error")
  plot_download <- function(p, plot_fn) downloadHandler(
    function() paste0("star_", p, "_plot.", input[[paste0(p, "_fmt")]] %||% "png"),
    function(file) star_ggsave(plot_fn(), file, width = 8, height = 5.6, dpi = as.numeric(input[[paste0(p, "_dpi")]] %||% 300)))
  notes_ui <- function(notes) if (length(notes)) div(class = "alert alert-warning", strong("Data checks"), tags$ul(lapply(notes, tags$li)))
  copy_button <- function(id, what, text) observeEvent(input[[id]], session$sendCustomMessage("copy_text", list(what = what, text = text())))

  # ---- correlation ----
  corr_dat <- use_data("corr", corr_setup)
  output$corr_data_ui <- renderUI(data_preview_ui(corr_dat()))
  output$corr_pickers <- renderUI({
    nm <- numeric_cols(corr_dat()); s <- example_of("corr", corr_setup)
    selectizeInput("corr_vars", "Variables (two or more)", nm, multiple = TRUE, selected = if (!is.null(s)) intersect(s$vars, nm) else head(nm, 6))
  })
  corr_res <- reactive({
    req(input$corr_vars)
    tryCatch(star_correlation(corr_dat(), input$corr_vars, input$corr_method, input$corr_alt, as.numeric(input$corr_alpha), input$corr_adjust), error = as_error)
  }) |> bindEvent(input$go_corr)
  corr_ok <- reactive({ r <- corr_res(); req(!inherits(r, "star_error")); r })
  corr_stale <- stale_flag("go_corr", reactive(list(input$corr_src, input$corr_example, input$corr_file$name, input$corr_vars, input$corr_method,
                                                    input$corr_alt, input$corr_adjust, input$corr_alpha)))
  output$corr_msg <- renderUI({
    if (!isTRUE(input$go_corr > 0)) return(run_hint("Run correlation"))
    r <- corr_res()
    tagList(if (corr_stale()) stale_note(), if (inherits(r, "star_error")) div(class = "alert alert-danger", r$message))
  })
  corr_tables <- reactive({ r <- corr_ok(); list(matrix = corr_matrix_display(r), pairs = corr_pairs_display(r)) })

  output$corr_results_ui <- renderUI({
    r <- corr_ok(); tb <- corr_tables()
    tagList(
      notes_ui(r$data_notes),
      div(class = if (any(r$pairs$Significant)) "alert alert-success" else "alert alert-info", r$summary),
      h4("Correlation matrix"), actionButton("cp_corr_matrix", "Copy table"), html_table(tb$matrix),
      p(class = "text-muted", sprintf("%s coefficient. * p < %s, ** p < 0.01, *** p < 0.001%s.", r$method_name, format(r$alpha),
                                     if (r$adjust != "none") paste0(" (", r$adjust, "-adjusted)") else "")),
      h4("All pairs"), actionButton("cp_corr_pairs", "Copy table"), html_table(tb$pairs),
      h4("APA-style report"), actionButton("cp_corr_apa", "Copy"), div(class = "well well-sm", lapply(r$apa, p)))
  })
  output$corr_view_picker <- renderUI({
    v <- corr_ok()$vars
    tagList(selectInput("corr_view", "Plot", c("Scatter plot matrix (all pairs)" = "matrix", "Heatmap of all pairs" = "heat", "Scatter plot of two variables" = "scatter")),
            conditionalPanel("input.corr_view == 'scatter'", fluidRow(
              column(6, selectInput("corr_x", "X axis", v, selected = v[1])),
              column(6, selectInput("corr_y", "Y axis", v, selected = v[2])))))
  })
  gg_corr <- reactive({
    r <- corr_ok(); v <- input$corr_view %||% "matrix"
    x <- input$corr_x; y <- input$corr_y
    pair <- if (v == "scatter" && !is.null(x) && !is.null(y) && x %in% r$vars && y %in% r$vars) {
      validate(need(x != y, "Choose two different variables for the scatter plot."))
      c(x, y)
    }
    star_ggplot_correlation(r, pair, main = input$corr_title, xlab = input$corr_xlab, ylab = input$corr_ylab,
                            type = if (v == "heat") "heatmap" else "matrix")
  })
  output$corr_plot <- renderPlot(print(gg_corr()))
  output$dl_corr_plot <- plot_download("corr", gg_corr)
  output$dl_corr_xlsx <- downloadHandler("star_correlation.xlsx", function(file) {
    r <- corr_ok(); tb <- corr_tables()
    mat <- function(m) data.frame(Variable = r$vars, m, check.names = FALSE, row.names = NULL)
    openxlsx::write.xlsx(list(`Correlation (r)` = mat(r$r), `P values` = mat(r$p), N = mat(r$n), Pairs = r$pairs,
                              Info = data.frame(Item = c("Method", "Alternative", "Alpha", "P adjustment", "Summary", "Data checks"),
                                                Value = c(r$method_name, r$alternative, r$alpha, r$adjust, r$summary,
                                                          if (length(r$data_notes)) paste(r$data_notes, collapse = " | ") else "none"))), file)
  })
  copy_button("cp_corr_matrix", "Correlation matrix", function() tsv(corr_tables()$matrix))
  copy_button("cp_corr_pairs", "Pairs table", function() tsv(corr_tables()$pairs))
  copy_button("cp_corr_apa", "APA text", function() paste(corr_ok()$apa, collapse = " "))

  # ---- regression ----
  reg_dat <- use_data("reg", reg_setup)
  output$reg_data_ui <- renderUI(data_preview_ui(reg_dat()))
  output$reg_pickers <- renderUI({
    nm <- numeric_cols(reg_dat()); s <- example_of("reg", reg_setup)
    resp <- if (!is.null(s)) s$resp else tail(nm, 1)
    tagList(selectInput("reg_resp", "Response variable (y)", nm, selected = resp),
            selectizeInput("reg_pred", "Predictor(s) (x): one or more", setdiff(nm, resp), multiple = TRUE,
                           selected = if (!is.null(s)) s$pred else head(setdiff(nm, resp), 1)))
  })
  observeEvent(input$reg_resp, {   # the response cannot also be a predictor
    nm <- numeric_cols(reg_dat()); keep <- setdiff(input$reg_pred, input$reg_resp)
    updateSelectizeInput(session, "reg_pred", choices = setdiff(nm, input$reg_resp), selected = keep)
  }, ignoreInit = TRUE)
  observeEvent(input$reg_example, { s <- reg_setup[[input$reg_example]]; if (!is.null(s)) updateRadioButtons(session, "reg_degree", selected = s$degree) })
  reg_res <- reactive({
    req(input$reg_resp, input$reg_pred)
    tryCatch(star_regression(reg_dat(), input$reg_resp, input$reg_pred, degree = if (length(input$reg_pred) == 1) as.integer(input$reg_degree) else 1L, alpha = as.numeric(input$reg_alpha)), error = as_error)
  }) |> bindEvent(input$go_reg)
  reg_ok <- reactive({ r <- reg_res(); req(!inherits(r, "star_error")); r })
  reg_stale <- stale_flag("go_reg", reactive(list(input$reg_src, input$reg_example, input$reg_file$name, input$reg_resp, input$reg_pred,
                                                  input$reg_degree, input$reg_alpha)))
  output$reg_msg <- renderUI({
    if (!isTRUE(input$go_reg > 0)) return(run_hint("Run regression"))
    r <- reg_res()
    tagList(if (reg_stale()) stale_note(), if (inherits(r, "star_error")) div(class = "alert alert-danger", r$message))
  })
  reg_tables <- reactive({ r <- reg_ok(); list(fit = reg_fit_display(r), anova = reg_anova_display(r), coef = reg_coef_display(r)) })

  output$reg_results_ui <- renderUI({
    r <- reg_ok(); tb <- reg_tables()
    tagList(
      notes_ui(r$data_notes),
      div(class = if (r$significant) "alert alert-success" else "alert alert-info", r$summary),
      h4("Fitted model"), div(class = "well well-sm", style = "font-family: monospace;", r$equation),
      h4("Model fit"), html_table(tb$fit),
      h4("Analysis of variance"), actionButton("cp_reg_anova", "Copy table"), html_table(tb$anova),
      h4("Parameter estimates"), actionButton("cp_reg_coef", "Copy table"), html_table(tb$coef),
      if (!is.null(r$optimum)) p(class = "text-muted", sprintf("Stationary point of the curve: %s = %s, fitted %s = %s (a %s%s).", r$predictors, fmt_sig(r$optimum$x), r$response,
                                                           fmt_sig(r$optimum$y), r$optimum$type, if (r$optimum$inside) "" else "; outside the range of the data")),
      h4("APA-style report"), actionButton("cp_reg_apa", "Copy"), div(class = "well well-sm", r$apa))
  })
  gg_reg <- reactive(star_ggplot_regression(reg_ok(), main = input$reg_title, xlab = input$reg_xlab, ylab = input$reg_ylab))
  output$reg_plot <- renderPlot(print(gg_reg()))
  output$dl_reg_plot <- plot_download("reg", gg_reg)
  output$reg_diag_ui <- renderUI({
    dg <- reg_ok()$diagnostics
    if (is.null(dg)) return(div(class = "alert alert-warning", "Assumption checks could not be computed for this data."))
    tagList(
      div(class = if (dg$ok) "alert alert-success" else "alert alert-warning", tags$ul(lapply(dg$messages, tags$li))),
      if (nrow(dg$outliers)) {
        o <- dg$outliers
        o[] <- lapply(o, function(v) if (is.numeric(v)) fmt_n(v, 3) else as.character(v))
        tagList(h4("Flagged observations"), p(class = "text-muted", "Row = row number in your data. |Studentized residual| > 3 = outlier, 2 to 3 = suspect."), html_table(o))
      })
  })
  output$reg_diag_plot <- renderPlot({ dg <- reg_ok()$diagnostics; req(dg); print(star_ggplot_diagnostics(dg)) })
  reg_predictions <- reactive({
    r <- reg_ok(); req(length(r$predictors) == 1, nzchar(trimws(input$reg_newx %||% "")))
    xs <- star_parse_number(trimws(strsplit(input$reg_newx, "[;,[:space:]]+")[[1]]))
    validate(need(length(xs) > 0 && !anyNA(xs), "Enter numbers separated by commas, for example: 40, 60, 80"))
    star_predict(r, setNames(data.frame(xs), r$predictors))
  })
  output$reg_predict_ui <- renderUI({
    r <- reg_ok()
    if (length(r$predictors) != 1) return(div(class = "alert alert-info", "Prediction is offered for a model with one predictor."))
    tagList(textInput("reg_newx", sprintf("Values of %s (separate with commas)", r$predictors), placeholder = "e.g. 40, 60, 80"),
            tableOutput("reg_pred_tbl"), p(class = "text-muted", "Predicted = fitted mean response; the interval is the confidence interval of that mean. Values outside the range of your data are extrapolations and are marked."))
  })
  output$reg_pred_tbl <- renderTable({
    z <- reg_predictions()
    data.frame(z[[1]], fmt_sig(z$Predicted), fmt_sig(z$Lower), fmt_sig(z$Upper), ifelse(z$Extrapolated, "yes", ""), check.names = FALSE, stringsAsFactors = FALSE) |>
      setNames(c(names(z)[1], "Predicted", "Lower CI", "Upper CI", "Extrapolated"))
  }, align = "r")
  output$dl_reg_xlsx <- downloadHandler("star_regression.xlsx", function(file) {
    r <- reg_ok(); dg <- r$diagnostics
    sheets <- list(Model = data.frame(Item = c("Response", "Predictor(s)", "Shape", "Equation", "Summary", "Data checks", names(unlist(r$fit))),
                                      Value = c(r$response, paste(r$predictors, collapse = ", "), c("line", "quadratic", "cubic")[r$degree], r$equation, r$summary,
                                                if (length(r$data_notes)) paste(r$data_notes, collapse = " | ") else "none", unlist(r$fit))),
                   ANOVA = r$anova, Coefficients = r$coefficients)
    if (!is.null(dg)) sheets$Residuals <- dg$residuals
    openxlsx::write.xlsx(sheets, file)
  })
  copy_button("cp_reg_anova", "ANOVA table", function() tsv(reg_tables()$anova))
  copy_button("cp_reg_coef", "Parameter estimates", function() tsv(reg_tables()$coef))
  copy_button("cp_reg_apa", "APA text", function() reg_ok()$apa)
}

shinyApp(ui, server)
